   563  static void
   564  exif_data_save_data_content (ExifData *data, ExifContent *ifd,
   565                               unsigned char **d, unsigned int *ds,
   566                               unsigned int offset)
   567  {
   568          unsigned int j, n_ptr = 0, n_thumb = 0;
   569          ExifIfd i;
   570          unsigned char *t;
